<?php

declare(strict_types=1);

namespace App\Calls\Supervision;

use App\Contracts\CallSender;
use App\Data\AskCard;
use App\Data\AskInbox;
use App\Support\CallKey;

/**
 * The signed calls of Supervision, generated by php artisan journal:calls; run it again instead of editing.
 */
final readonly class SupervisionCalls
{
    public function __construct(private CallSender $sender) {}

    public function listAsks(
        string|null $before = null,
    ): AskInbox {
        return $this->sender->send(ListAsksCall::from([
            'before' => $before,
        ]));
    }

    public function makeAsk(
        CallKey $requestKey,
        string $body,
        string|null $type = null,
    ): AskCard {
        return $this->sender->send(MakeAskCall::from([
            'requestKey' => $requestKey,
            'body' => $body,
            'type' => $type,
        ]));
    }

    public function replyToAsk(
        CallKey $requestKey,
        string $id,
        string $body,
    ): AskCard {
        return $this->sender->send(ReplyToAskCall::from([
            'requestKey' => $requestKey,
            'id' => $id,
            'body' => $body,
        ]));
    }

    public function showAsk(
        string $id,
    ): AskCard {
        return $this->sender->send(ShowAskCall::from([
            'id' => $id,
        ]));
    }

    public function withdrawAsk(
        CallKey $requestKey,
        string $id,
    ): AskCard {
        return $this->sender->send(WithdrawAskCall::from([
            'requestKey' => $requestKey,
            'id' => $id,
        ]));
    }
}
